import type { Actor } from "../authz/actor.js";
import { agencyWrite, allow, type Decision, deny, isAdminOf, membershipRoleIn } from "../authz/decision.js";

/** The package row's scope. `agencyId: null` = generated by a network admin. */
export interface InspectionPackageResource { networkId: string; agencyId: string | null }
export interface InspectionRevokeResource extends InspectionPackageResource { createdBy: string }

export type InspectionAction = "inspection:use" | "inspection:read" | "inspection:revoke";
export interface InspectionResources {
  "inspection:use": Record<string, never>;
  "inspection:read": InspectionPackageResource;
  "inspection:revoke": InspectionRevokeResource;
}

// ESCALATION.md Option D: network admin, or the OWNER of the active agency. Managers, viewers and nurses never.
const readPackage = (actor: Actor, r: InspectionPackageResource): Decision => {
  if (actor.role === "admin") return isAdminOf(actor, r.networkId) ? allow : deny("out_of_scope");
  if (actor.role === "agency") {
    const ok = r.agencyId !== null && actor.activeAgencyId === r.agencyId && membershipRoleIn(actor, r.agencyId) === "owner";
    return ok ? allow : deny("out_of_scope"); // hidden: 404
  }
  return deny("role_not_permitted");
};

export const inspectionPolicy: { [A in InspectionAction]: (actor: Actor, r: InspectionResources[A]) => Decision } = {
  // Gate for every inspection route: who may use the feature at all (scope is checked per nurse / per package).
  "inspection:use": (actor) => {
    if (actor.role === "admin") return actor.networkIds.length > 0 ? allow : deny("not_a_member");
    if (actor.role === "agency") return agencyWrite(actor, null, ["owner"]);
    return deny("role_not_permitted");
  },
  "inspection:read": readPackage,
  // The creator, or a network admin of the package's network. An agency owner who is not the creator cannot revoke another's package.
  "inspection:revoke": (actor, r) => {
    const read = readPackage(actor, r);
    if (!read.allow) return read;
    return actor.userId === r.createdBy || isAdminOf(actor, r.networkId) ? allow : deny("resource_rule");
  },
};
